import { readFile, rm, writeFile } from "node:fs/promises";

export async function snapshotNextEnv(path) {
  try {
    return { exists: true, bytes: await readFile(path) };
  } catch (error) {
    if (error?.code === "ENOENT") return { exists: false, bytes: null };
    throw error;
  }
}

export async function captureBenchmarkNextEnv(path, distName) {
  const snapshot = await snapshotNextEnv(path);
  if (!snapshot.exists || !snapshot.bytes.includes(Buffer.from(distName))) return null;
  return snapshot;
}

/**
 * Restore only the exact generated bytes this benchmark observed. A current
 * file that no longer references this run, or that changed after capture, is
 * owned by another process/person and must never be overwritten.
 */
export async function restoreBenchmarkNextEnv({ path, distName, before, generated }) {
  if (!before || !generated?.exists || !generated.bytes) return "unchanged";
  const current = await snapshotNextEnv(path);
  if (!current.exists || !current.bytes) return "skipped-concurrent-change";
  if (!current.bytes.includes(Buffer.from(distName))) return "skipped-concurrent-change";
  if (!current.bytes.equals(generated.bytes)) return "skipped-concurrent-change";

  if (before.exists && before.bytes) {
    await writeFile(path, before.bytes);
    return "restored";
  }
  await rm(path, { force: true });
  return "deleted";
}
